"""Python exercise lessons from exercises.json, generated by `manage.py import_exercises <docx>`."""

import json
from functools import cache
from pathlib import Path

from .code_runner import outputs_match, run_python

EXERCISES_PATH = Path(__file__).with_name("exercises.json")
# Fields the page may show before an exercise is solved; solutions and explanations stay on the server.
PUBLIC_FIELDS = ("id", "kind", "title", "object", "task", "expected_output", "hint", "starting_code", "timer_seconds")


@cache
def load_exercise_lessons() -> dict[str, dict]:
    """Return lesson data by LessonID, e.g. "building1_room1", "building1_jumpscare", "building1_boss"."""
    return {lesson["lesson_id"]: lesson for lesson in json.loads(EXERCISES_PATH.read_text(encoding="utf-8"))}


class ExerciseLesson:
    """A room's Python exercises; the room is complete once every exercise prints its expected output."""

    def __init__(self, lesson: dict):
        self.lesson = lesson
        self.exercises = lesson["exercises"]
        self.default_requirements = {"exercises": [exercise["id"] for exercise in self.exercises]}
        if lesson["kind"] == "jumpscare":
            self.instructions = "A zombie jumps out! Click it, then fix the broken code before the timer runs out."
        elif lesson["kind"] == "boss":
            self.instructions = f"Boss fight! Click the zombie and write one program that uses {self.exercises[0]['uses']}"
        else:
            self.instructions = f"This room teaches {lesson['teaches']} Click each object, then write Python that prints the expected output."

    def public_exercises(self) -> list[dict]:
        """Return each exercise without its solution or explanation, for the page."""
        return [{field: exercise.get(field) for field in PUBLIC_FIELDS} for exercise in self.exercises]

    def check_exercise(self, exercise_id: str, code: str) -> dict:
        """Run code with exec() and return its output, error, whether it matched, and feedback."""
        exercise = next((exercise for exercise in self.exercises if exercise["id"] == exercise_id), None)
        if exercise is None:
            raise ValueError("This exercise is not in this room.")
        result = run_python(code)
        result["passed"] = not result["error"] and outputs_match(result["output"], exercise["expected_output"])
        if result["passed"]:
            result["feedback"] = "✓ Correct! " + exercise["explanation"]
        elif result["error"]:
            result["feedback"] = "✗ Your program crashed. Read the error, fix the code and run it again."
        else:
            result["feedback"] = "✗ The output doesn't match the expected output yet."
        return result
